-- Place-name corpus, used as the default conversation title for new
-- user_bot conversations. Same words the iOS welcome-screen randomizer
-- picks from (apps/ios/PendingBot/Resources/names.txt), checked in
-- here so server-side conv creation (bootstrap_user_id, the
-- open_user_bot_conv RPC) can use them too.

create table if not exists pendingbot.place_names (
  name text primary key
);

alter table pendingbot.place_names enable row level security;
drop policy if exists place_names_authenticated_read on pendingbot.place_names;
create policy place_names_authenticated_read
  on pendingbot.place_names for select
  using (auth.role() = 'authenticated');

truncate table pendingbot.place_names;
